import{_ as o,o as a,c as r,a3 as t}from"./chunks/framework.DEy3KOfk.js";const u=JSON.parse('{"title":"Interface: MapperOptions","description":"","frontmatter":{"editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/tools/port-mapping/src/mapper.ts"},"headers":[],"relativePath":"api/tools/@pumpkin-plugins/port-mapping/mapper/interfaces/MapperOptions.md","filePath":"docs/api/tools/@pumpkin-plugins/port-mapping/mapper/interfaces/MapperOptions.md","lastUpdated":null}'),s={name:"api/tools/@pumpkin-plugins/port-mapping/mapper/interfaces/MapperOptions.md"};function i(n,e,p,d,c,l){return a(),r("div",null,[...e[0]||(e[0]=[t('<p><a href="./../../">@pumpkin-plugins/port-mapping API</a> / <a href="./../">mapper</a> / MapperOptions</p><h1 id="interface-mapperoptions" tabindex="-1">Interface: MapperOptions <a class="header-anchor" href="#interface-mapperoptions" aria-label="Permalink to &quot;Interface: MapperOptions&quot;">​</a></h1><p>Defined in: <a href="https://github.com/filiphsps/pumpkin-plugins/blob/62b294b880d999bf876c094c99d9e3eb44680d37/tools/port-mapping/src/mapper.ts#L41" target="_blank" rel="noreferrer">tools/port-mapping/src/mapper.ts:41</a></p><p>Settings of a <code>PortMapper</code>.</p><h2 id="extends" tabindex="-1">Extends <a class="header-anchor" href="#extends" aria-label="Permalink to &quot;Extends&quot;">​</a></h2><ul><li><code>Omit</code>&lt;<a href="./../../discover/interfaces/DiscoveryOptions"><code>DiscoveryOptions</code></a>, <code>&quot;searchMs&quot;</code>&gt;</li></ul><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to &quot;Properties&quot;">​</a></h2><h3 id="leaseseconds" tabindex="-1">leaseSeconds <a class="header-anchor" href="#leaseseconds" aria-label="Permalink to &quot;leaseSeconds&quot;">​</a></h3><blockquote><p><strong>leaseSeconds</strong>: <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/filiphsps/pumpkin-plugins/blob/62b294b880d999bf876c094c99d9e3eb44680d37/tools/port-mapping/src/mapper.ts#L43" target="_blank" rel="noreferrer">tools/port-mapping/src/mapper.ts:43</a></p><p>How long routers keep a mapping without a renewal. Renewed at half this time.</p><hr><h3 id="log" tabindex="-1">log? <a class="header-anchor" href="#log" aria-label="Permalink to &quot;log?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>log?</strong>: (<code>message</code>, <code>level?</code>) =&gt; <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/filiphsps/pumpkin-plugins/blob/62b294b880d999bf876c094c99d9e3eb44680d37/tools/port-mapping/src/mapper.ts#L50" target="_blank" rel="noreferrer">tools/port-mapping/src/mapper.ts:50</a></p><p>Where messages for the server log go. Failures come with the level <code>warn</code>, and each is said once until a port opens, so a router that stays away doesn&#39;t fill the log.</p><h4 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="message" tabindex="-1">message <a class="header-anchor" href="#message" aria-label="Permalink to &quot;message&quot;">​</a></h5><p><code>string</code></p><h5 id="level" tabindex="-1">level? <a class="header-anchor" href="#level" aria-label="Permalink to &quot;level?&quot;">​</a></h5><p><code>&quot;info&quot;</code> | <code>&quot;warn&quot;</code></p><h4 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>void</code></p><hr><h3 id="natpmp" tabindex="-1">natPmp <a class="header-anchor" href="#natpmp" aria-label="Permalink to &quot;natPmp&quot;">​</a></h3><blockquote><p><strong>natPmp</strong>: <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/filiphsps/pumpkin-plugins/blob/62b294b880d999bf876c094c99d9e3eb44680d37/tools/port-mapping/src/discover.ts#L18" target="_blank" rel="noreferrer">tools/port-mapping/src/discover.ts:18</a></p><p>Look for NAT-PMP gateways.</p><h4 id="inherited-from" tabindex="-1">Inherited from <a class="header-anchor" href="#inherited-from" aria-label="Permalink to &quot;Inherited from&quot;">​</a></h4><p><a href="./../../discover/interfaces/DiscoveryOptions"><code>DiscoveryOptions</code></a>.<a href="./../../discover/interfaces/DiscoveryOptions#natpmp"><code>natPmp</code></a></p><hr><h3 id="natpmpgateway" tabindex="-1">natPmpGateway? <a class="header-anchor" href="#natpmpgateway" aria-label="Permalink to &quot;natPmpGateway?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>natPmpGateway?</strong>: <a href="./../../ipv4/interfaces/Endpoint"><code>Endpoint</code></a></p></blockquote><p>Defined in: <a href="https://github.com/filiphsps/pumpkin-plugins/blob/62b294b880d999bf876c094c99d9e3eb44680d37/tools/port-mapping/src/discover.ts#L22" target="_blank" rel="noreferrer">tools/port-mapping/src/discover.ts:22</a></p><p>The NAT-PMP gateway to use. Without it the usual router addresses of the local network are tried.</p><h4 id="inherited-from-1" tabindex="-1">Inherited from <a class="header-anchor" href="#inherited-from-1" aria-label="Permalink to &quot;Inherited from&quot;">​</a></h4><p><a href="./../../discover/interfaces/DiscoveryOptions"><code>DiscoveryOptions</code></a>.<a href="./../../discover/interfaces/DiscoveryOptions#natpmpgateway"><code>natPmpGateway</code></a></p><hr><h3 id="onrefused" tabindex="-1">onRefused? <a class="header-anchor" href="#onrefused" aria-label="Permalink to &quot;onRefused?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>onRefused?</strong>: (<code>refusal</code>) =&gt; <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/filiphsps/pumpkin-plugins/blob/62b294b880d999bf876c094c99d9e3eb44680d37/tools/port-mapping/src/mapper.ts#L52" target="_blank" rel="noreferrer">tools/port-mapping/src/mapper.ts:52</a></p><p>Called once when the <code>screen</code> turns the router down. The mapper logs nothing about it.</p><h4 id="parameters-1" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-1" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="refusal" tabindex="-1">refusal <a class="header-anchor" href="#refusal" aria-label="Permalink to &quot;refusal&quot;">​</a></h5><h6 id="identity" tabindex="-1">identity <a class="header-anchor" href="#identity" aria-label="Permalink to &quot;identity&quot;">​</a></h6><p><a href="./../../identify/interfaces/RouterIdentity"><code>RouterIdentity</code></a></p><h6 id="reason" tabindex="-1">reason <a class="header-anchor" href="#reason" aria-label="Permalink to &quot;reason&quot;">​</a></h6><p><code>string</code></p><h4 id="returns-1" tabindex="-1">Returns <a class="header-anchor" href="#returns-1" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>void</code></p><hr><h3 id="random" tabindex="-1">random? <a class="header-anchor" href="#random" aria-label="Permalink to &quot;random?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>random?</strong>: () =&gt; <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/filiphsps/pumpkin-plugins/blob/62b294b880d999bf876c094c99d9e3eb44680d37/tools/port-mapping/src/mapper.ts#L54" target="_blank" rel="noreferrer">tools/port-mapping/src/mapper.ts:54</a></p><p>A number in [0, 1), for choosing another public port when the first is taken.</p><h4 id="returns-2" tabindex="-1">Returns <a class="header-anchor" href="#returns-2" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>number</code></p><hr><h3 id="screen" tabindex="-1">screen? <a class="header-anchor" href="#screen" aria-label="Permalink to &quot;screen?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>screen?</strong>: <a href="./../../identify/type-aliases/Screen"><code>Screen</code></a></p></blockquote><p>Defined in: <a href="https://github.com/filiphsps/pumpkin-plugins/blob/62b294b880d999bf876c094c99d9e3eb44680d37/tools/port-mapping/src/discover.ts#L30" target="_blank" rel="noreferrer">tools/port-mapping/src/discover.ts:30</a></p><p>Turns routers down by what they are. It sees every router that gives away its make and model, before anything is asked of it, and a router it gives a reason for is not used: when that leaves no router, discovery throws a <code>RouterRefusedError</code>. Without it routers are not identified.</p><h4 id="inherited-from-2" tabindex="-1">Inherited from <a class="header-anchor" href="#inherited-from-2" aria-label="Permalink to &quot;Inherited from&quot;">​</a></h4><p><a href="./../../discover/interfaces/DiscoveryOptions"><code>DiscoveryOptions</code></a>.<a href="./../../discover/interfaces/DiscoveryOptions#screen"><code>screen</code></a></p><hr><h3 id="searchms" tabindex="-1">searchMs? <a class="header-anchor" href="#searchms" aria-label="Permalink to &quot;searchMs?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>searchMs?</strong>: <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/filiphsps/pumpkin-plugins/blob/62b294b880d999bf876c094c99d9e3eb44680d37/tools/port-mapping/src/mapper.ts#L45" target="_blank" rel="noreferrer">tools/port-mapping/src/mapper.ts:45</a></p><p>How long a UPnP search waits for answers.</p><hr><h3 id="ssdp" tabindex="-1">ssdp? <a class="header-anchor" href="#ssdp" aria-label="Permalink to &quot;ssdp?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>ssdp?</strong>: <a href="./../../ipv4/interfaces/Endpoint"><code>Endpoint</code></a></p></blockquote><p>Defined in: <a href="https://github.com/filiphsps/pumpkin-plugins/blob/62b294b880d999bf876c094c99d9e3eb44680d37/tools/port-mapping/src/discover.ts#L20" target="_blank" rel="noreferrer">tools/port-mapping/src/discover.ts:20</a></p><p>Where to send UPnP searches. Defaults to the SSDP multicast group; a router&#39;s own address works when multicast is blocked.</p><h4 id="inherited-from-3" tabindex="-1">Inherited from <a class="header-anchor" href="#inherited-from-3" aria-label="Permalink to &quot;Inherited from&quot;">​</a></h4><p><a href="./../../discover/interfaces/DiscoveryOptions"><code>DiscoveryOptions</code></a>.<a href="./../../discover/interfaces/DiscoveryOptions#ssdp"><code>ssdp</code></a></p><hr><h3 id="upnp" tabindex="-1">upnp <a class="header-anchor" href="#upnp" aria-label="Permalink to &quot;upnp&quot;">​</a></h3><blockquote><p><strong>upnp</strong>: <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/filiphsps/pumpkin-plugins/blob/62b294b880d999bf876c094c99d9e3eb44680d37/tools/port-mapping/src/discover.ts#L16" target="_blank" rel="noreferrer">tools/port-mapping/src/discover.ts:16</a></p><p>Look for UPnP gateways.</p><h4 id="inherited-from-4" tabindex="-1">Inherited from <a class="header-anchor" href="#inherited-from-4" aria-label="Permalink to &quot;Inherited from&quot;">​</a></h4><p><a href="./../../discover/interfaces/DiscoveryOptions"><code>DiscoveryOptions</code></a>.<a href="./../../discover/interfaces/DiscoveryOptions#upnp"><code>upnp</code></a></p>',83)])])}const m=o(s,[["render",i]]);export{u as __pageData,m as default};
